{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated evaluation is neither documented nor explicitly ruled out."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7: reinterpret test-retest as repeated evaluation of an unchanged AI system. Repeatability evidence is insufficient, corresponding to 0, not demonstrated inadequacy (1). Human retest considerations are inapplicable here. Exact-grid scoring involves no stated judgement, making inter-rater reliability in 9.6 inapplicable."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly denies repeated evaluation."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeat observations, stability is unestablished; the passage does not demonstrate unstable scores."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7: repeated evaluation of the unchanged system is the AI reinterpretation of retest evidence. Its explicit absence leaves repeatability unrateable (0), rather than demonstrating poor repeatability (1). Human retest considerations are inapplicable."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage documents repeated scores under unchanged conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stability: at most two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 permits alternative precision evidence: the repeated-run range supports consistency for this system and these conditions. This reinterprets human retesting as AI reruns. The passage's stability rule is not an EFPA coefficient threshold; it does not establish broader temporal stability or justify an excellent overall reliability rating under 9.8."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage documents repeated evaluation under unchanged conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "This range exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7: reinterpret human retesting as unchanged-system reruns and evaluate the reported range as alternative precision evidence. Unlike missing evidence, the observed variation demonstrates inadequate stability for the stated comparison rule. Under 9.8, this limits reliance on an individual run for comparisons."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not document repeated evaluation."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence of score consistency."
        }
      ],
      "instrument_review": "EFPA 6.3.8 concerns software instructions; their addition does not establish reliability under 9.3 or 9.7. Reinterpret retesting as AI reruns: repeatability remains unrateable (0), not demonstrated inadequate (1). Human retest considerations are inapplicable, and documentation quality remains distinct from psychometric quality."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher exact-grid score on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The observed comparison supplies no evidence establishing superiority across domains."
        }
      ],
      "instrument_review": "EFPA 10.1 and 10.5 require evidence appropriate to the intended interpretation. Here, that interpretation is limited to evaluated grid performance; the observed comparison supports it descriptively. General intelligence is unestablished, not disproved. Reinterpret examinees as AI systems; human demographic questions are inapplicable to this comparison."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better on the evaluated grid puzzles, regardless of the broader intended use."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "An intended cross-domain interpretation does not establish it empirically."
        }
      ],
      "instrument_review": "EFPA 6.1.1, 10.1, 10.3 and 10.5: the broad intended use requires a construct rationale and evidence supporting cross-domain interpretation. The supplied grid results leave that validity unrateable (0), not proof that A lacks greater general intelligence. Treat validity as critical for this selection purpose: EFPA restricts such unsupported use to research or exceptional expert circumstances. Examinees are reinterpreted as AI systems; human demographic questions are inapplicable."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Test scores alone supply no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "Random allocation, blinded correctness checks and a difference interval of 12 to 28 percentage points support better correctness with A in the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an improvement in the unmeasured safety outcome."
        }
      ],
      "instrument_review": "EFPA 10.3.1.6 and 10.3.2 recognize experimental evidence and relevant external criteria. Reinterpret the criterion as correctness of human decisions assisted by each AI system. The preregistered randomized trial supports the stated workshop use, with blinded checks and reported uncertainty. The 120 inspectors are trial participants, not an AI norm sample; no automatic sample-size rating is warranted. Under 10.5, the evidence supports a bounded correctness claim, not safety, speed, or generalization beyond the studied conditions."
    }
  ],
  "closing_note": "No task instruction required clarification. The explicit probe-level format was followed instead of completing eight full forms. Original EFPA sections guided the reviews; AI reinterpretations and relevant inapplicable human-testing questions are recorded. Labels classify statements, not EFPA ratings. Missing evidence is distinguished from demonstrated inadequacy. No aggregate quality score was calculated, and no EFPA endorsement is implied."
}
